<template>
 <main class="quiz-app stack"><header class="topbar"><div><p class="eyebrow">Quiz Results · Learning Analytics</p><h1>{{ data?.quiz.title || 'Hasil Quiz' }}</h1><p class="muted">Pantau pencapaian kelas dan temukan materi yang perlu diperkuat.</p></div><router-link class="button" :to="data?.quiz.course_id ? `/kelas/${data.quiz.course_id}` : `/kelas`">← Kembali ke Kelas</router-link></header><div v-if="error" class="error" role="alert">{{ error }}</div><p v-if="loading" class="empty">Menghitung statistik…</p><template v-if="data"><div class="stats"><div v-for="[key,label] in metrics" :key="key" class="stat"><span class="muted">{{ label }}</span><strong>{{ data.statistics[key] ?? '—' }}{{ key === 'pass_rate' && data.statistics[key] != null ? '%' : '' }}</strong></div><div class="stat"><span class="muted">Rata-rata durasi</span><strong>{{ Math.round(data.statistics.average_completion_seconds / 60) }}m</strong></div></div><p class="muted">Statistik nilai memakai metode {{ data.quiz.grading_method }} per student. {{ data.statistics.graded }} student sudah mendapat nilai final; essay yang belum diperiksa tidak masuk statistik nilai.</p><section class="panel stack"><div class="row" style="justify-content:space-between"><h2>Nilai Student</h2><button @click="load">Refresh</button></div><div class="form-grid"><input v-model="search" placeholder="Cari student…" aria-label="Cari student"><select v-model="classFilter" aria-label="Filter kelas"><option value="">Seluruh kelas</option><option v-for="c in data.classes" :key="c.name" :value="c.name">{{ c.name }}</option></select></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Kelas</th><th>Mulai</th><th>Submit</th><th>Durasi</th><th>Benar</th><th>Salah</th><th>Nilai</th><th>Nilai akhir</th><th>Status</th><th>Attempt</th><th></th></tr></thead><tbody><tr v-for="a in filtered" :key="a.id"><td>{{ a.name }}</td><td>{{ a.classes.join(', ') || 'Individual' }}</td><td>{{ dateLabel(a.started_at) }}</td><td>{{ dateLabel(a.submitted_at) }}</td><td>{{ a.duration_seconds == null ? '—' : Math.floor(a.duration_seconds/60) + 'm ' + a.duration_seconds%60 + 's' }}</td><td>{{ a.total_correct }}</td><td>{{ a.total_wrong }}</td><td>{{ a.score ?? '—' }}</td><td>{{ a.aggregate_score ?? '—' }}</td><td><span class="badge">{{ a.status === 'IN_PROGRESS' ? 'Dikerjakan' : a.pending_review ? 'Periksa essay' : Number(a.score) >= Number(data.quiz.passing_grade) ? 'Lulus' : 'Tidak lulus' }}</span></td><td>{{ a.attempt_number }}</td><td><button @click="detail(a.id)">Detail Jawaban</button></td></tr></tbody></table></div><p v-if="!filtered.length" class="empty">Belum ada attempt.</p></section><div class="grid"><section class="panel stack"><h2>Performa Kelas</h2><article v-for="c in data.classes" :key="c.name"><h3>{{ c.name }}</h3><p class="muted">{{ c.participants }} peserta · {{ c.graded }} dinilai · Rata-rata {{ c.average_score ?? '—' }} · Lulus {{ c.pass_rate ?? '—' }}%</p><div class="progress"><span :style="{width:(c.average_score || 0) + '%'}"></span></div></article></section><section class="panel stack"><h2>5 Pertanyaan Paling Sulit</h2><article v-for="q in data.hardest_questions" :key="q.id"><p>{{ q.question }}</p><p class="muted">Benar {{ q.correct_rate }}% · Salah/tidak dijawab {{ q.wrong_rate }}% · {{ q.difficulty }}</p><div class="progress"><span :style="{width:q.correct_rate + '%'}"></span></div></article><p v-if="!data.hardest_questions.length" class="muted">Analisis tersedia setelah quiz dikumpulkan.</p></section></div><section class="panel stack"><h2>Analisis Seluruh Soal</h2><div class="table-wrap"><table><thead><tr><th>Pertanyaan</th><th>Difficulty</th><th>Respons dinilai</th><th>Benar</th><th>Salah / Kosong</th></tr></thead><tbody><tr v-for="q in data.questions" :key="q.id"><td style="white-space:normal;min-width:250px">{{ q.question }}</td><td>{{ q.difficulty }}</td><td>{{ q.responses }}</td><td>{{ q.correct_rate }}%</td><td>{{ q.wrong_rate }}%</td></tr></tbody></table></div></section></template>
 <div v-if="selected" class="overlay" @click.self="selected = null"><section class="dialog stack" style="width:min(850px,100%)" role="dialog" aria-modal="true" aria-labelledby="review-title"><header class="row" style="justify-content:space-between"><div><h2 id="review-title">{{ selected.student }}</h2><p class="muted">Attempt #{{ selected.attempt_number }} · {{ selected.status }}</p></div><button @click="selected = null">Tutup</button></header><p v-if="reviewError" class="error">{{ reviewError }}</p><article v-for="q in selected.questions" :key="q.id" class="panel stack"><h3>{{ q.position }}. {{ q.question }}</h3><img v-if="q.image_url" :src="q.image_url" alt="Gambar soal" class="question-image" /><p v-if="q.type === 'essay'" class="prewrap">{{ q.essay || 'Tidak dijawab' }}</p><div v-for="o in q.options" :key="o.id" class="option" :class="{picked:q.selected_options.includes(o.id)}"><span>{{ o.text }}</span><span v-if="o.is_correct" class="badge">Kunci</span><span v-if="q.selected_options.includes(o.id)" class="muted">Dipilih</span></div><p class="muted">Poin: {{ q.points ?? 'Belum dinilai' }} / {{ q.weight }}</p><form v-if="q.type === 'essay' && selected.status !== 'IN_PROGRESS'" class="stack" @submit.prevent="grade(q)"><label class="field">Nilai essay<input v-model.number="q.grade" type="number" min="0" :max="q.weight" step="0.01" required></label><label class="field">Feedback<textarea v-model="q.feedback"></textarea></label><button class="primary" :disabled="busy">Simpan Nilai</button></form><p v-if="q.explanation" class="muted prewrap">{{ q.explanation }}</p></article></section></div>
 </main>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue';
import { useRoute } from '@/navigation';
import { api, errorMessage, dateLabel } from './api';
import './quiz.css';
const route = useRoute(), data = ref(null), error = ref(''), reviewError = ref(''), loading = ref(true), selected = ref(null), search = ref(''), classFilter = ref(''), busy = ref(false);
const metrics = [['participants','Total peserta'],['completed','Selesai'],['not_started','Belum mulai'],['average_score','Rata-rata nilai'],['highest_score','Nilai tertinggi'],['lowest_score','Nilai terendah'],['pass_rate','Pass rate']];
const filtered = computed(() => (data.value?.attempts || []).filter(a => a.name.toLowerCase().includes(search.value.toLowerCase()) && (!classFilter.value || a.classes.includes(classFilter.value))));
async function load() { try { data.value = await api('get',`manage/${route.params.id}/results`); error.value = ''; } catch(e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function detail(id) { try { selected.value = await api('get',`results/${id}`); selected.value.questions.forEach(q => q.grade = q.points); reviewError.value = ''; } catch(e) { error.value = errorMessage(e); } }
async function grade(q) { busy.value = true; try { await api('put',`results/${selected.value.id}/grade/${q.id}`,{points:q.grade,feedback:q.feedback}); await detail(selected.value.id); await load(); } catch(e) { reviewError.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
</script>
